// Access to the generated book content.
//
// The real content lives in public/libro/ (generated by contenido/generar.py) and is fetched
// lazily, one part at a time. When it is missing (fresh checkout, pipeline not run yet) the app
// falls back to the small hand-written sample in src/lib/muestra/, which follows the same schema.

import type { DocBusqueda, EntradaGlosario, Indice, InfoParte, Parte, Refs } from './tipos';

type Modo = 'libro' | 'muestra';

const BASE_LIBRO = 'libro/';

// Sample content: JSON loaded on demand, assets resolved to their bundled URLs.
const jsonMuestra = import.meta.glob<unknown>('./muestra/**/*.json', { import: 'default' });
const urlsMuestra = import.meta.glob<string>('./muestra/**/*.{svg,jpg,jpeg,png,webp}', {
  query: '?url',
  import: 'default',
  eager: true,
});

let modo: Modo = 'libro';
let indice: Indice | null = null;
let refs: Refs = {};
const partes = new Map<string, Promise<Parte>>();
let glosario: Promise<EntradaGlosario[]> | null = null;
let busqueda: Promise<DocBusqueda[]> | null = null;

async function leerLibro<T>(ruta: string): Promise<T> {
  const r = await fetch(BASE_LIBRO + ruta);
  if (!r.ok) throw new Error(`No se pudo cargar ${ruta} (${r.status})`);
  const tipo = r.headers.get('content-type') ?? '';
  // The Vite dev server answers unknown paths with index.html: treat that as "missing".
  if (tipo.includes('text/html')) throw new Error(`No existe ${ruta}`);
  return (await r.json()) as T;
}

async function leerMuestra<T>(ruta: string): Promise<T> {
  const cargar = jsonMuestra[`./muestra/${ruta}`];
  if (!cargar) throw new Error(`La muestra no contiene ${ruta}`);
  return (await cargar()) as T;
}

export function leerJSON<T>(ruta: string): Promise<T> {
  return modo === 'libro' ? leerLibro<T>(ruta) : leerMuestra<T>(ruta);
}

/** URL of an asset referenced by the content (fig/…, img/…, ec/…). */
export function url(ruta: string): string {
  if (/^(https?:|data:|blob:)/.test(ruta)) return ruta;
  const limpia = ruta.replace(/^\.?\//, '');
  if (modo === 'muestra') return urlsMuestra[`./muestra/${limpia}`] ?? limpia;
  return BASE_LIBRO + limpia;
}

/** Loads the index and the reference table; decides between the real book and the sample. */
export async function iniciar(): Promise<{ indice: Indice; refs: Refs; modo: Modo }> {
  try {
    // «?muestra» in the URL forces the sample (handy to test the renderer against every block type).
    if (new URLSearchParams(location.search).has('muestra')) throw new Error('muestra');
    modo = 'libro';
    const [i, r] = await Promise.all([leerLibro<Indice>('indice.json'), leerLibro<Refs>('refs.json')]);
    indice = i;
    refs = r;
  } catch {
    modo = 'muestra';
    const [i, r] = await Promise.all([leerMuestra<Indice>('indice.json'), leerMuestra<Refs>('refs.json')]);
    indice = i;
    refs = r;
  }
  return { indice, refs, modo };
}

export function obtenerIndice(): Indice {
  if (!indice) throw new Error('Índice no cargado');
  return indice;
}

export function obtenerRefs(): Refs {
  return refs;
}

export function modoContenido(): Modo {
  return modo;
}

export function cargarParte(id: string): Promise<Parte> {
  let p = partes.get(id);
  if (!p) {
    p = leerJSON<Parte>(`partes/${id}.json`);
    p.catch(() => partes.delete(id));
    partes.set(id, p);
  }
  return p;
}

export function cargarGlosario(): Promise<EntradaGlosario[]> {
  glosario ??= leerJSON<EntradaGlosario[]>('glosario.json');
  return glosario;
}

export function cargarBusqueda(): Promise<DocBusqueda[]> {
  busqueda ??= leerJSON<DocBusqueda[]>('busqueda.json');
  return busqueda;
}

// ------------------------------------------------------------------ reading order

/** All parts in reading order: the volumes first, then any part not listed in a volume. */
export function ordenLectura(): string[] {
  const i = obtenerIndice();
  const vistos = new Set<string>();
  const orden: string[] = [];
  for (const t of i.tomos) {
    for (const p of t.partes) {
      if (!vistos.has(p) && i.partes[p]) {
        vistos.add(p);
        orden.push(p);
      }
    }
  }
  for (const p of Object.keys(i.partes)) if (!vistos.has(p)) orden.push(p);
  return orden;
}

export function infoParte(id: string): InfoParte | undefined {
  return indice?.partes[id];
}

/** «Capítulo 5», «Apéndice A», or the title for back matter. */
export function rotuloParte(id: string): string {
  const p = infoParte(id);
  if (!p) return id;
  if (p.tipo === 'capitulo' && p.num != null) return `Capítulo ${p.num}`;
  if (p.tipo === 'apendice' && p.num != null) return `Apéndice ${p.num}`;
  return p.titulo;
}

/** Short title shown in the top bar and in lists. */
export function tituloCorto(id: string): string {
  const p = infoParte(id);
  if (!p) return id;
  const t = p.titulo.split(' — ')[0] ?? p.titulo;
  return p.num != null && (p.tipo === 'capitulo' || p.tipo === 'apendice') ? `${p.num} · ${t}` : t;
}

/** The volume a part belongs to (by the index), if any. */
export function tomoDe(id: string): string | undefined {
  const i = obtenerIndice();
  const p = i.partes[id];
  if (p?.tomo) return p.tomo;
  return i.tomos.find((t) => t.partes.includes(id))?.id;
}

// ------------------------------------------------------------------ references

/** Hash route of a reference key, or null if the key is unknown. */
export function rutaDeRef(clave: string): string | null {
  const r = refs[clave];
  if (!r) return null;
  return `#/${r.parte}/${encodeURIComponent(clave)}`;
}

/**
 * DOM ids that may hold the target of a reference key. Aliases (old labels) share the entry of
 * their target but not its id, so the canonical «tipo-num» label and every key with the same
 * entry are tried as well.
 */
export function candidatosDeRef(clave: string): string[] {
  const r = refs[clave];
  const lista = [clave];
  if (!r) return lista;
  if (r.label) lista.unshift(r.label);
  lista.push(`${r.tipo}-${r.num}`);
  for (const [k, v] of Object.entries(refs)) {
    if (k !== clave && v.parte === r.parte && v.tipo === r.tipo && v.num === r.num) lista.push(k);
  }
  return [...new Set(lista)];
}

// ------------------------------------------------------------------ HTML fragments

const cacheHtml = new Map<string, string>();

/** CSS url() of a URL, safe for data: URLs that contain quotes. */
export function urlCss(u: string): string {
  return `url("${u.replace(/"/g, '%22').replace(/\n/g, '')}")`;
}

function escaparAtributo(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/"/g, '&quot;');
}

/**
 * Adapts a trusted HTML fragment of the pipeline to the app:
 * - asset paths (ec/…, fig/…, img/…) are resolved to real URLs;
 * - inline equations (img.m) are painted with currentColor through a CSS mask, so they follow
 *   the theme: the image keeps the layout (intrinsic size) and the mask gives the shape;
 * - references (a.ref) get a real hash href, so they work as ordinary links.
 */
export function prepararHtml(html: string | null | undefined): string {
  if (!html) return '';
  const hit = cacheHtml.get(html);
  if (hit !== undefined) return hit;
  let out = html.replace(/<img\b([^>]*?)\/?>/g, (_m, attrs: string) => {
    let a = attrs;
    let u = '';
    a = a.replace(/\bsrc="([^"]*)"/, (_s, src: string) => {
      u = url(src);
      return `src="${escaparAtributo(u)}"`;
    });
    if (/\bclass="[^"]*\bm\b[^"]*"/.test(a) && u) {
      const mask = `-webkit-mask-image:${urlCss(u)};mask-image:${urlCss(u)};`;
      if (/\bstyle="/.test(a)) a = a.replace(/\bstyle="([^"]*)"/, (_s, st: string) => `style="${st.replace(/;?\s*$/, ';')}${escaparAtributo(mask)}"`);
      else a += ` style="${escaparAtributo(mask)}"`;
      a += ' decoding="async" draggable="false"';
    } else {
      a += ' loading="lazy" decoding="async"';
    }
    return `<img${a}>`;
  });
  out = out.replace(/<a\b([^>]*?)>/g, (m, attrs: string) => {
    const k = /data-ref="([^"]*)"/.exec(attrs)?.[1];
    if (!k || /\bhref=/.test(attrs)) return m;
    const ruta = rutaDeRef(k);
    return ruta ? `<a${attrs} href="${escaparAtributo(ruta)}">` : `<a${attrs} aria-disabled="true">`;
  });
  cacheHtml.set(html, out);
  return out;
}

/** Plain text of an HTML fragment (for titles, aria labels and search snippets). */
export function textoPlano(html: string | null | undefined): string {
  if (!html) return '';
  return html
    .replace(/<img\b[^>]*\balt="([^"]*)"[^>]*>/g, ' $1 ')
    .replace(/<br\s*\/?>/g, ' ')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&amp;/g, '&')
    .replace(/\s+/g, ' ')
    .trim();
}

/** Accent- and case-insensitive form of a text (ñ folds to n, as a forgiving search expects). */
export function normalizar(s: string): string {
  return s.toLowerCase().normalize('NFD').replace(/\p{M}/gu, '');
}

/** Initial letter of a glossary term for grouping: accents removed, Ñ kept, digits grouped. */
export function letraDe(termino: string): string {
  const c = textoPlano(termino).trim().charAt(0).toUpperCase();
  if (c === 'Ñ') return 'Ñ';
  const base = c.normalize('NFD').replace(/\p{M}/gu, '');
  return /[A-Z]/.test(base) ? base : '#';
}

/** DOM id of a glossary entry (also the id the sample uses for glossary search documents). */
export function idGlosario(termino: string): string {
  return (
    'glo-' +
    normalizar(textoPlano(termino))
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-|-$/g, '')
  );
}
